type AuthContextValue = { user: User | null; loading: boolean };
const AuthContext = createContext<AuthContextValue>({ user: null, loading: true });
const useAuth = () => useContext(AuthContext);

type Flight = {
  id: string; source: 'internal' | 'duffel'; airline: string; airlineCode?: string; flightNumber: string;
  origin: string; destination: string; departureTime: string; arrivalTime: string; durationMinutes?: number;
  duration?: string; stops?: number; amountMinor?: number; amount?: number; currency: string;
  availableSeats?: number; cabinClass?: string; bookable: boolean; providerMessage?: string; expiresAt?: string;
};
type Booking = {
  id: string; bookingReference: string; flightId: string; flightNumber: string; airlineName: string; paymentStatus?: string;
  originCode: string; destinationCode: string; departureTime: string; arrivalTime: string;
  status: string; totalAmountMinor: number; currency: string; seatCount: number; holdExpiresAt?: string;
  passengers: Array<{ givenName: string; familyName: string }>;
};
type Organization = { id: string; name: string; type: 'airline' | 'travel_agency'; country: string; currency: string; status: string; role: string };
type Passenger = { id: string; givenName: string; familyName: string; dateOfBirth: string; email?: string; phoneNumber?: string };

function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    if (!auth) { setLoading(false); return; }
    return onAuthStateChanged(auth, (next) => { setUser(next); setLoading(false); });
  }, []);
  return <AuthContext.Provider value={{ user, loading }}>{children}</AuthContext.Provider>;
}

function Brand({ light = false }: { light?: boolean }) {
  return <Link to="/" className={`inline-flex items-center gap-2.5 font-display text-xl font-extrabold tracking-tight ${light ? 'text-white' : 'text-navy'}`}><span className="grid h-9 w-9 place-items-center rounded-xl bg-aviation text-white"><Plane size={19}/></span>AeroNexa<span className="text-gold">.</span></Link>;
}

