function FormField({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="mb-4 block"><span className="mb-2 block text-xs font-extrabold uppercase tracking-wider text-slate-500">{label}</span>{children}{hint && <span className="mt-1 block text-xs text-slate-400">{hint}</span>}</label>;
}

function AuthPage({ mode }: { mode: 'signin' | 'register' }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const next = params.get('next')?.startsWith('/app') ? params.get('next')! : '/app';
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      if (!auth || !firebaseConfigured) throw new Error('Authentication is not configured. Add the Firebase web settings to apps/web/.env.local.');
      if (mode === 'register') {
        const credential = await createUserWithEmailAndPassword(auth, email.trim(), password);
        if (displayName.trim()) await updateProfile(credential.user, { displayName: displayName.trim() });
        await setDoc(doc(getFirestore(), 'users', credential.user.uid), { uid: credential.user.uid, email: credential.user.email, displayName: displayName.trim(), status: 'active', createdAt: serverTimestamp() });
      } else await signInWithEmailAndPassword(auth, email.trim(), password);
      navigate(next, { replace: true });
    } catch (err) {
      const code = typeof err === 'object' && err !== null && 'code' in err && typeof err.code === 'string' ? err.code : '';
      setError(code === 'auth/configuration-not-found'
        ? 'Firebase Authentication is not configured for this project. In Firebase Console, open Authentication and complete setup, then enable Email/Password under Sign-in method. Confirm the web app uses this same Firebase project and restart the dev server.'
        : err instanceof Error ? err.message : 'Authentication failed.');
    }
    finally { setBusy(false); }
  };
  return <div className="grid min-h-screen bg-white lg:grid-cols-2"><div className="hidden min-h-screen flex-col justify-between bg-navy p-12 text-white lg:flex"><Brand light/><div className="max-w-lg"><p className="text-xs font-extrabold uppercase tracking-[.2em] text-sky-200">AeroNexa workspace</p><h1 className="mt-4 text-5xl font-extrabold leading-tight">Every trip, in one clear view.</h1><p className="mt-5 text-base leading-7 text-slate-300">Search routes, manage your bookings and keep travel details connected wherever you go.</p></div><p className="text-xs text-slate-400">Secure account access for your travel workspace.</p></div><div className="flex min-h-screen items-center justify-center px-6 py-12"><div className="w-full max-w-md"><Link to="/" className="mb-10 inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-aviation"><ArrowRight className="rotate-180" size={16}/> Back home</Link><div className="mb-8 lg:hidden"><Brand/></div><p className="text-xs font-extrabold uppercase tracking-[.2em] text-aviation">Welcome {mode === 'signin' ? 'back' : 'aboard'}</p><h2 className="mt-3 text-3xl font-extrabold text-navy">{mode === 'signin' ? 'Sign in to AeroNexa' : 'Create your account'}</h2><p className="mt-3 text-sm text-slate-500">{mode === 'signin' ? 'Access bookings, travellers and your travel documents.' : 'Create a secure account to plan and manage your journeys.'}</p><form onSubmit={submit} className="mt-8">{mode === 'register' && <FormField label="Full name"><input className="form-input" value={displayName} onChange={(e) => setDisplayName(e.target.value)} required autoComplete="name"/></FormField>}<FormField label="Email address"><input className="form-input" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required autoComplete="email"/></FormField><FormField label="Password"><input className="form-input" type="password" minLength={8} value={password} onChange={(e) => setPassword(e.target.value)} required autoComplete={mode === 'signin' ? 'current-password' : 'new-password'}/></FormField>{error && <div className="mb-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{error}</div>}<button disabled={busy} className="mt-1 flex w-full items-center justify-center gap-2 rounded-xl bg-aviation px-5 py-3.5 text-sm font-extrabold text-white hover:bg-navy disabled:opacity-60">{busy ? 'Please wait...' : mode === 'signin' ? 'Sign in' : 'Create account'} <ArrowRight size={16}/></button></form><p className="mt-7 text-center text-sm text-slate-500">{mode === 'signin' ? 'New to AeroNexa?' : 'Already have an account?'} <Link to={mode === 'signin' ? '/register' : '/signin'} className="font-extrabold text-aviation">{mode === 'signin' ? 'Create an account' : 'Sign in'}</Link></p><div className="mt-8 flex items-center justify-center gap-2 text-xs text-slate-400"><LockKeyhole size={13}/> Protected by Firebase Authentication</div></div></div></div>;
}

function Protected({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  const location = useLocation();
  if (loading) return <FullPageLoading/>;
  if (!user) return <Navigate to={`/signin?next=${encodeURIComponent(location.pathname + location.search)}`} replace/>;
  return <>{children}</>;
}

function FullPageLoading() { return <div className="grid min-h-screen place-items-center bg-slate-50"><div className="text-center"><div className="mx-auto h-10 w-10 animate-spin rounded-full border-4 border-sky border-t-aviation"/><p className="mt-4 text-sm font-semibold text-slate-500">Loading AeroNexa...</p></div></div>; }
function LoadingLine() { return <div className="flex items-center gap-2 py-8 text-sm font-semibold text-slate-400"><RefreshCw className="animate-spin" size={16}/> Loading your information...</div>; }
function ErrorNotice({ message }: { message: string }) { return <div className="flex gap-3 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800"><AlertCircle className="mt-0.5 shrink-0" size={17}/><span>{message}</span></div>; }
function SuccessNotice({ message }: { message: string }) { return <div className="flex gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800"><CheckCircle2 className="mt-0.5 shrink-0" size={17}/><span>{message}</span></div>; }
function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) { return <div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-[.18em] text-aviation">{eyebrow}</p><h1 className="mt-2 text-3xl font-extrabold text-navy">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p>}</div>{action}</div>; }
function StatusPill({ value }: { value: string }) { const good = ['ticketed', 'confirmed', 'active', 'succeeded', 'issued', 'checked_in', 'accepted'].includes(value); const bad = ['cancelled', 'failed', 'expired', 'suspended'].includes(value); return <span className={`inline-flex rounded-full px-3 py-1 text-[11px] font-extrabold capitalize ${good ? 'bg-emerald-50 text-emerald-700' : bad ? 'bg-rose-50 text-rose-700' : 'bg-amber-50 text-amber-700'}`}>{value.replaceAll('_', ' ')}</span>; }
function currency(amountMinor: number, code = 'KES') { try { return new Intl.NumberFormat('en-KE', { style: 'currency', currency: code, maximumFractionDigits: 2 }).format(amountMinor / 100); } catch { return `${code} ${(amountMinor / 100).toFixed(2)}`; } }
function dateLabel(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('en-KE', { dateStyle: 'medium', timeStyle: 'short' }).format(date); }
function inputDateOffset(days: number) { const d = new Date(); d.setDate(d.getDate() + days); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }

function SearchFlightsPage({ compact = false }: { compact?: boolean }) {
  const [params] = useSearchParams();
  const [origin, setOrigin] = useState(params.get('from')?.match(/\(([A-Z]{3})\)/)?.[1] ?? params.get('from') ?? 'NBO');
  const [destination, setDestination] = useState(params.get('to')?.match(/\(([A-Z]{3})\)/)?.[1] ?? params.get('to') ?? 'LHR');
  const [departureDate, setDepartureDate] = useState(params.get('depart') ?? inputDateOffset(30));
  const [returnDate, setReturnDate] = useState(inputDateOffset(37));
  const [adults, setAdults] = useState(1);
  const [cabinClass, setCabinClass] = useState('economy');
  const [flights, setFlights] = useState<Flight[]>([]);
  const [warning, setWarning] = useState('');
  const [error, setError] = useState('');
  const [searched, setSearched] = useState(false);
  const [busy, setBusy] = useState(false);
  const [roundTrip, setRoundTrip] = useState(false);
  const navigate = useNavigate();
  const { user } = useAuth();

  useEffect(() => {
    const from = params.get('from'); const to = params.get('to'); const dep = params.get('depart');
    if (from) setOrigin(from.match(/\(([A-Z]{3})\)/)?.[1] ?? from);
    if (to) setDestination(to.match(/\(([A-Z]{3})\)/)?.[1] ?? to);
    if (dep) setDepartureDate(dep);
  }, [params]);

  const search = async (event?: FormEvent) => {
    event?.preventDefault(); setBusy(true); setError(''); setWarning(''); setSearched(true);
    try {
      const query = new URLSearchParams({ origin: origin.trim().toUpperCase(), destination: destination.trim().toUpperCase(), departureDate, adults: String(adults), cabinClass });
      if (roundTrip) query.set('returnDate', returnDate);
      const result = await apiRequest<{ flights: Flight[]; supplierWarning?: string | null }>(`/flights/search?${query.toString()}`);
      setFlights(result.flights); setWarning(result.supplierWarning ?? '');
    } catch (err) { setFlights([]); setError(err instanceof Error ? err.message : 'Could not search flights.'); }
    finally { setBusy(false); }
  };
  const swap = () => { setOrigin(destination); setDestination(origin); };

  return <div className={compact ? 'relative z-10 -mt-16 rounded-3xl border border-white/70 bg-white p-5 shadow-[0_24px_70px_rgba(16,36,58,.16)] md:p-7' : ''}>
    {compact && <div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><div className="grid h-9 w-9 place-items-center rounded-xl bg-sky text-aviation"><Plane size={17}/></div><div><p className="text-sm font-extrabold text-navy">Find your next flight</p><p className="text-xs text-slate-400">Search live internal schedules and configured suppliers</p></div></div><span className="flex items-center gap-2 text-xs font-semibold text-slate-500"><ShieldCheck size={15} className="text-aviation"/> Secure booking experience</span></div>}
    {!compact && <PageTitle eyebrow="Flight discovery" title="Search flights" description="Compare published AeroNexa schedules and external supplier offers where configured."/>}
    <form onSubmit={search} className="rounded-2xl border border-slate-200 bg-white p-4 md:p-5">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-2"><button type="button" onClick={() => setRoundTrip(false)} className={`rounded-full px-4 py-2 text-xs font-extrabold ${!roundTrip ? 'bg-navy text-white' : 'bg-slate-100 text-slate-600'}`}>One way</button><button type="button" onClick={() => setRoundTrip(true)} className={`rounded-full px-4 py-2 text-xs font-extrabold ${roundTrip ? 'bg-navy text-white' : 'bg-slate-100 text-slate-600'}`}>Round trip</button></div><span className="text-xs font-semibold text-slate-400">Up to 9 passengers</span></div>
      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-[1fr_1fr_1fr_1fr_.75fr_auto] xl:items-end">
        <FormField label="From airport"><div className="relative"><MapPin className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-aviation" size={17}/><input className="form-input pl-10 uppercase" value={origin} onChange={(e) => setOrigin(e.target.value.toUpperCase())} maxLength={3} required placeholder="NBO"/></div></FormField>
        <div className="flex items-end"><button type="button" onClick={swap} className="mb-4 flex h-12 w-full items-center justify-center gap-2 rounded-xl border border-slate-200 text-sm font-bold text-slate-500 hover:bg-sky hover:text-aviation"><ArrowLeftRight size={16}/> Swap airports</button></div>
        <FormField label="To airport"><div className="relative"><MapPin className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-aviation" size={17}/><input className="form-input pl-10 uppercase" value={destination} onChange={(e) => setDestination(e.target.value.toUpperCase())} maxLength={3} required placeholder="LHR"/></div></FormField>
        <FormField label="Departure"><input type="date" min={inputDateOffset(0)} className="form-input" value={departureDate} onChange={(e) => setDepartureDate(e.target.value)} required/></FormField>
        {roundTrip && <FormField label="Return"><input type="date" min={departureDate} className="form-input" value={returnDate} onChange={(e) => setReturnDate(e.target.value)} required/></FormField>}
        <FormField label="Travellers"><select className="form-input" value={adults} onChange={(e) => setAdults(Number(e.target.value))}>{Array.from({ length: 9 }, (_, i) => <option key={i + 1} value={i + 1}>{i + 1} {i === 0 ? 'Adult' : 'Adults'}</option>)}</select></FormField>
        <FormField label="Cabin"><select className="form-input" value={cabinClass} onChange={(e) => setCabinClass(e.target.value)}><option value="economy">Economy</option><option value="premium_economy">Premium economy</option><option value="business">Business</option><option value="first">First</option></select></FormField>
      </div>
      {roundTrip && <p className="mt-3 rounded-lg bg-amber-50 p-3 text-xs leading-5 text-amber-800">Round-trip searches use the configured supplier when available. Internal inventory currently supports one-way, single-leg bookings, and supplier offers are not bookable yet.</p>}
      <div className="flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-slate-400">Airport codes are used for accurate route matching (for example NBO, MBA, LHR).</p><button disabled={busy} className="flex h-12 items-center justify-center gap-2 rounded-xl bg-aviation px-6 text-sm font-extrabold text-white transition hover:bg-navy disabled:opacity-60"><Search size={17}/>{busy ? 'Searching...' : 'Search flights'}</button></div>
    </form>
    {!compact && (error || warning) && <div className="mt-4">{error ? <ErrorNotice message={error}/> : <div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800">{warning}</div>}</div>}
    {searched && <div className="mt-6">{busy ? <LoadingLine/> : <><div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-extrabold text-navy">{flights.length} flight options</h2><span className="text-xs text-slate-400">{origin} to {destination} · {departureDate}</span></div>{flights.length === 0 ? <div className="rounded-2xl border border-dashed border-slate-300 p-8 text-center"><PlaneTakeoff className="mx-auto text-slate-300" size={28}/><h3 className="mt-3 font-extrabold text-navy">No published flights found</h3><p className="mt-2 text-sm text-slate-500">Try another date or route. Internal inventory must be published by an airline or operator.</p></div> : <div className="grid gap-3">{flights.map((flight) => <FlightResult key={`${flight.source}-${flight.id}`} flight={flight} onBook={() => navigate(user ? `/app/book/${flight.id}?adults=${adults}` : `/signin?next=${encodeURIComponent(`/app/book/${flight.id}?adults=${adults}`)}`, { state: { flight } })}/>)}</div>}</>}</div>}
    {!compact && !searched && <div className="mt-5 grid gap-3 sm:grid-cols-3">{[{ title: 'Internal inventory', text: 'Published schedules with transactional seat holds.' }, { title: 'Supplier search', text: 'External offers when your Duffel credentials are configured.' }, { title: 'Secure checkout', text: 'M-Pesa and card payment channels with server-side verification.' }].map((item) => <div key={item.title} className="rounded-xl bg-sky/60 p-4"><p className="text-sm font-extrabold text-navy">{item.title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{item.text}</p></div>)}</div>}
  </div>;
}

function FlightResult({ flight, onBook }: { flight: Flight; onBook: () => void }) {
  const price = flight.amountMinor ?? Math.round((flight.amount ?? 0) * 100);
  return <article className="grid gap-4 rounded-2xl border border-slate-200 bg-white p-5 md:grid-cols-[1.3fr_1.2fr_.8fr_auto] md:items-center"><div className="flex items-center gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-sky text-aviation"><Plane size={20}/></div><div><p className="font-extrabold text-navy">{flight.airline}</p><p className="mt-1 text-xs text-slate-400">{flight.flightNumber} · {flight.source === 'internal' ? 'AeroNexa inventory' : 'External supplier'}</p></div></div><div className="flex items-center gap-4"><div><p className="text-lg font-extrabold text-navy">{new Date(flight.departureTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p><p className="text-xs font-bold text-slate-500">{flight.origin}</p></div><div className="min-w-16 flex-1 text-center"><div className="text-[10px] text-slate-400">{flight.durationMinutes ? `${Math.floor(flight.durationMinutes / 60)}h ${flight.durationMinutes % 60}m` : flight.duration ?? 'Flight'}</div><div className="relative my-1 h-px bg-slate-200"><span className="absolute -top-1.5 left-1/2 h-3 w-3 -translate-x-1/2 rounded-full border-2 border-aviation bg-white"/></div><div className="text-[10px] text-slate-400">{flight.stops ? `${flight.stops} stop(s)` : 'Non-stop'}</div></div><div><p className="text-lg font-extrabold text-navy">{new Date(flight.arrivalTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p><p className="text-xs font-bold text-slate-500">{flight.destination}</p></div></div><div><p className="text-xl font-extrabold text-navy">{currency(price, flight.currency)}</p><p className="mt-1 text-xs text-slate-400">per passenger · {flight.cabinClass ?? 'economy'}</p></div><div className="flex flex-col gap-2"><button onClick={onBook} disabled={!flight.bookable} className="rounded-xl bg-aviation px-5 py-3 text-xs font-extrabold text-white hover:bg-navy disabled:cursor-not-allowed disabled:bg-slate-300">{flight.bookable ? 'Book flight' : 'Not bookable yet'}</button>{!flight.bookable && <span className="max-w-40 text-[10px] leading-4 text-slate-400">{flight.providerMessage ?? 'Supplier payment settlement is not enabled.'}</span>}</div></article>;
}

function DashboardLayout() {
  const { user } = useAuth();
  const [mobile, setMobile] = useState(false);
  const navItems = [
    { label: 'Overview', path: '/app', icon: LayoutDashboard, end: true },
    { label: 'Search flights', path: '/app/flights', icon: Search },
    { label: 'My bookings', path: '/app/bookings', icon: Ticket },
    { label: 'Passengers', path: '/app/passengers', icon: UsersRound },
    { label: 'Payments', path: '/app/payments', icon: CreditCard },
    { label: 'E-tickets', path: '/app/tickets', icon: PlaneTakeoff },
    { label: 'Travel documents', path: '/app/documents', icon: Luggage },
    { label: 'Organizations', path: '/app/organizations', icon: Building2 },
    { label: 'Flight operations', path: '/app/operations', icon: ClipboardList },
    { label: 'Notifications', path: '/app/notifications', icon: Bell },
    { label: 'Settings', path: '/app/settings', icon: Settings },
  ];
  const navigate = useNavigate();
  const handleSignOut = async () => { if (auth) await signOut(auth); navigate('/'); };
  return <div className="min-h-screen bg-[#F5F8FC]"><div className="flex min-h-screen"><aside className={`fixed inset-y-0 left-0 z-50 flex w-[270px] flex-col bg-navy px-4 py-5 text-white transition-transform md:sticky md:top-0 md:h-screen md:translate-x-0 ${mobile ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between px-2"><Brand light/><button onClick={() => setMobile(false)} className="rounded-lg p-2 text-white/70 md:hidden"><X/></button></div><div className="mt-8 rounded-2xl border border-white/10 bg-white/5 p-4"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-sky-200">Personal workspace</p><p className="mt-2 truncate text-sm font-extrabold">{user?.displayName || user?.email || 'Traveller'}</p><p className="mt-1 truncate text-xs text-slate-400">{user?.email}</p></div><nav className="mt-7 flex-1 space-y-1 overflow-y-auto">{navItems.map(({ label, path, icon: Icon, end }) => <NavLink key={path} to={path} end={end} onClick={() => setMobile(false)} className={({ isActive }) => `flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold transition ${isActive ? 'bg-white text-navy shadow-sm' : 'text-slate-300 hover:bg-white/10 hover:text-white'}`}><Icon size={17}/>{label}</NavLink>)}</nav><div className="mt-5 border-t border-white/10 pt-4"><InstallAppButton/><button onClick={handleSignOut} className="mt-3 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold text-slate-300 hover:bg-white/10 hover:text-white"><LogOut size={17}/> Sign out</button></div></aside>
    {mobile && <button aria-label="Close navigation" onClick={() => setMobile(false)} className="fixed inset-0 z-40 bg-navy/50 md:hidden"/>}
    <div className="min-w-0 flex-1"><header className="sticky top-0 z-30 flex h-[76px] items-center justify-between border-b border-slate-200 bg-white px-5 md:px-9"><div className="flex items-center gap-3"><button onClick={() => setMobile(true)} className="rounded-lg p-2 text-navy md:hidden"><Menu/></button><div><p className="text-xs text-slate-400">AeroNexa workspace</p><p className="text-sm font-extrabold text-navy">Your travel, connected</p></div></div><div className="flex items-center gap-3"><Link to="/app/notifications" className="relative rounded-full p-2 text-slate-500 hover:bg-slate-100"><Bell size={19}/></Link><div className="grid h-9 w-9 place-items-center rounded-full bg-sky text-sm font-extrabold text-aviation">{(user?.displayName || user?.email || 'A').slice(0, 1).toUpperCase()}</div></div></header><main className="mx-auto max-w-[1500px] p-5 md:p-9"><Routes><Route index element={<DashboardHome/>}/><Route path="flights" element={<SearchFlightsPage/>}/><Route path="book/:flightId" element={<CreateBookingPage/>}/><Route path="bookings" element={<BookingsPage/>}/><Route path="passengers" element={<PassengersPage/>}/><Route path="payments" element={<PaymentsPage/>}/><Route path="tickets" element={<TicketsPage/>}/><Route path="documents" element={<DocumentsPage/>}/><Route path="organizations" element={<OrganizationsPage/>}/><Route path="invitations/:inviteId" element={<AcceptInvitationPage/>}/><Route path="operations" element={<FlightOperationsPage/>}/><Route path="notifications" element={<NotificationsPage/>}/><Route path="settings" element={<SettingsPage/>}/><Route path="*" element={<Navigate to="/app" replace/>}/></Routes></main></div></div></div>;
}

function DashboardHome() {
  const { user } = useAuth();
  const [summary, setSummary] = useState<Record<string, number> | null>(null);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [error, setError] = useState('');
  useEffect(() => { Promise.all([apiRequest<{ summary: Record<string, number> }>('/dashboard/summary'), apiRequest<{ bookings: Booking[] }>('/bookings')]).then(([s, b]) => { setSummary(s.summary); setBookings(b.bookings.slice(0, 4)); }).catch((err) => setError(err instanceof Error ? err.message : 'Could not load dashboard.')); }, []);
  return <><PageTitle eyebrow="Your travel overview" title={`Welcome, ${user?.displayName?.split(' ')[0] || 'traveller'}.`} description="Here is a quick view of your upcoming travel and account activity." action={<Link to="/app/flights" className="rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white hover:bg-navy"><Search className="mr-2 inline" size={16}/>Find a flight</Link>}/>{error && <ErrorNotice message={error}/>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ label: 'Upcoming trips', value: summary?.upcomingTrips ?? '—', icon: PlaneTakeoff }, { label: 'Active bookings', value: summary?.activeBookings ?? '—', icon: Ticket }, { label: 'Saved passengers', value: summary?.savedPassengers ?? '—', icon: UsersRound }, { label: 'Unread notifications', value: summary?.unreadNotifications ?? '—', icon: Bell }].map((card) => <div key={card.label} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><span className="text-sm font-semibold text-slate-500">{card.label}</span><span className="grid h-10 w-10 place-items-center rounded-xl bg-sky text-aviation"><card.icon size={19}/></span></div><div className="mt-4 text-3xl font-extrabold text-navy">{card.value}</div></div>)}</div><div className="mt-7 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><section className="rounded-2xl border border-slate-200 bg-white p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-extrabold text-navy">Recent bookings</h2><p className="mt-1 text-sm text-slate-500">Your latest reservations and seat holds.</p></div><Link to="/app/bookings" className="text-xs font-extrabold text-aviation">View all <ArrowRight className="ml-1 inline" size={14}/></Link></div>{bookings.length === 0 ? <div className="mt-6 rounded-xl bg-sky/60 p-5"><p className="font-extrabold text-navy">Your next destination is waiting</p><p className="mt-1 text-sm text-slate-500">Search available routes and reserve your first trip.</p><Link to="/app/flights" className="mt-4 inline-flex items-center gap-2 text-sm font-extrabold text-aviation">Explore flights <ArrowRight size={16}/></Link></div> : <div className="mt-5 divide-y divide-slate-100">{bookings.map((booking) => <BookingRow key={booking.id} booking={booking}/>)}</div>}</section><section className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="text-lg font-extrabold text-navy">Quick actions</h2><p className="mt-1 text-sm text-slate-500">Manage your travel details.</p><div className="mt-5 grid gap-2">{[{ label: 'Save a passenger', path: '/app/passengers', icon: UsersRound }, { label: 'Review payments', path: '/app/payments', icon: WalletCards }, { label: 'Open e-tickets', path: '/app/tickets', icon: Ticket }, { label: 'Manage documents', path: '/app/documents', icon: FileText }, { label: 'Set up an organization', path: '/app/organizations', icon: Building2 }].map((action) => <Link key={action.path} to={action.path} className="flex items-center justify-between rounded-xl border border-slate-100 p-3 text-sm font-bold text-slate-600 hover:border-sky hover:bg-sky/50 hover:text-navy"><span className="flex items-center gap-3"><action.icon size={17} className="text-aviation"/>{action.label}</span><ChevronRight size={15}/></Link>)}</div></section></div><div className="mt-6 flex flex-wrap items-center gap-3 rounded-2xl border border-sky-100 bg-sky/60 p-5"><ShieldCheck className="text-aviation"/><div className="flex-1"><p className="text-sm font-extrabold text-navy">Secure by design</p><p className="mt-1 text-xs text-slate-600">Booking and payment records are managed through authenticated server workflows.</p></div><Link to="/app/settings" className="text-xs font-extrabold text-aviation">Account settings <ArrowRight className="ml-1 inline" size={14}/></Link></div></>;
}

function BookingRow({ booking }: { booking: Booking }) {
  return <div className="flex flex-wrap items-center justify-between gap-3 py-4"><div><p className="font-extrabold text-navy">{booking.originCode} <ArrowRight className="mx-1 inline" size={13}/> {booking.destinationCode}</p><p className="mt-1 text-xs text-slate-400">{booking.bookingReference} · {booking.flightNumber} · {dateLabel(booking.departureTime)}</p></div><div className="flex items-center gap-3"><StatusPill value={booking.status}/><span className="text-sm font-extrabold text-navy">{currency(booking.totalAmountMinor, booking.currency)}</span></div></div>;
}

function CreateBookingPage() {
  const { flightId = '' } = useParams();
  const [searchParams] = useSearchParams();
  const requestedAdults = Math.max(1, Math.min(9, Number(searchParams.get('adults') || 1)));
  const [flight, setFlight] = useState<Record<string, any> | null>(null);
  const [passengers, setPassengers] = useState(() => Array.from({ length: requestedAdults }, () => ({ givenName: '', familyName: '', dateOfBirth: '1990-01-01', email: '', phoneNumber: '' }))); 
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const navigate = useNavigate();
  const { user } = useAuth();
  useEffect(() => { apiRequest<{ flight: Record<string, any> }>(`/flights/${flightId}`).then((result) => setFlight(result.flight)).catch((err) => setError(err instanceof Error ? err.message : 'Flight unavailable.')); }, [flightId]);
  const updatePassenger = (index: number, key: string, value: string) => setPassengers((current) => current.map((p, i) => i === index ? { ...p, [key]: value } : p));
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const result = await apiRequest<{ booking: Booking }>('/bookings', { method: 'POST', body: JSON.stringify({ flightId, passengers }) });
      setSuccess(`Seats held for 15 minutes. Booking reference ${result.booking.bookingReference}.`);
      navigate(`/app/payments?booking=${result.booking.id}`, { state: { booking: result.booking } });
    } catch (err) { setError(err instanceof Error ? err.message : 'Could not reserve seats.'); }
    finally { setBusy(false); }
  };
  useEffect(() => { if (user?.email) setPassengers((current) => current.map((p, index) => index === 0 ? { ...p, email: p.email || user.email || '', givenName: p.givenName || user.displayName?.split(' ')[0] || '', familyName: p.familyName || user.displayName?.split(' ').slice(1).join(' ') || '' } : p)); }, [user]);
  if (!flight && !error) return <LoadingLine/>;
  return <><PageTitle eyebrow="Secure reservation" title="Passenger details" description="Review the flight and enter passenger names exactly as they appear on travel documents." action={<Link to="/app/flights" className="text-sm font-bold text-aviation">Back to search</Link>}/>{error && <ErrorNotice message={error}/>}{success && <SuccessNotice message={success}/>}{flight && <div className="grid gap-6 xl:grid-cols-[1fr_340px]"><form onSubmit={submit} className="rounded-2xl border border-slate-200 bg-white p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-navy">Passenger information</p><p className="mt-1 text-xs text-slate-400">{passengers.length} passenger(s) · Up to 9 per booking</p></div><button type="button" disabled={passengers.length >= 9} onClick={() => setPassengers((current) => [...current, { givenName: '', familyName: '', dateOfBirth: '1990-01-01', email: user?.email ?? '', phoneNumber: '' }])} className="flex items-center gap-1 rounded-lg bg-sky px-3 py-2 text-xs font-extrabold text-aviation disabled:opacity-40"><Plus size={14}/> Add passenger</button></div>{passengers.map((passenger, index) => <div key={index} className="mb-5 rounded-xl border border-slate-100 p-4"><div className="mb-4 flex items-center justify-between"><p className="text-sm font-extrabold text-navy">Passenger {index + 1}</p>{passengers.length > 1 && <button type="button" onClick={() => setPassengers((current) => current.filter((_, i) => i !== index))} className="text-xs font-bold text-rose-600">Remove</button>}</div><div className="grid gap-4 sm:grid-cols-2"><FormField label="First / given name"><input required className="form-input" value={passenger.givenName} onChange={(e) => updatePassenger(index, 'givenName', e.target.value)}/></FormField><FormField label="Last / family name"><input required className="form-input" value={passenger.familyName} onChange={(e) => updatePassenger(index, 'familyName', e.target.value)}/></FormField><FormField label="Date of birth"><input required type="date" max={inputDateOffset(-1)} className="form-input" value={passenger.dateOfBirth} onChange={(e) => updatePassenger(index, 'dateOfBirth', e.target.value)}/></FormField><FormField label="Email address"><input type="email" className="form-input" value={passenger.email} onChange={(e) => updatePassenger(index, 'email', e.target.value)} placeholder="Optional"/></FormField><FormField label="Phone number"><input className="form-input" value={passenger.phoneNumber} onChange={(e) => updatePassenger(index, 'phoneNumber', e.target.value)} placeholder="Optional"/></FormField></div></div>)}{error && <div className="mb-4"><ErrorNotice message={error}/></div>}<div className="rounded-xl bg-sky/60 p-4 text-xs leading-5 text-slate-600"><ShieldCheck size={15} className="mr-2 inline text-aviation"/> Your seat inventory is held atomically for 15 minutes. Complete payment before the hold expires.</div><button disabled={busy} className="mt-5 w-full rounded-xl bg-aviation px-5 py-3.5 text-sm font-extrabold text-white hover:bg-navy disabled:opacity-60">{busy ? 'Holding seats...' : 'Continue to payment'} <ArrowRight className="ml-2 inline" size={16}/></button></form><aside className="h-fit rounded-2xl border border-slate-200 bg-white p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-aviation">Your flight</p><h2 className="mt-3 text-xl font-extrabold text-navy">{flight.airlineName}</h2><p className="mt-1 text-sm text-slate-500">{flight.flightNumber}</p><div className="my-6 flex items-center justify-between"><div><p className="text-2xl font-extrabold text-navy">{flight.originCode}</p><p className="mt-1 text-xs text-slate-400">{dateLabel(flight.departureTime)}</p></div><Plane className="text-aviation"/><div className="text-right"><p className="text-2xl font-extrabold text-navy">{flight.destinationCode}</p><p className="mt-1 text-xs text-slate-400">{dateLabel(flight.arrivalTime)}</p></div></div><div className="border-t border-slate-100 pt-4"><div className="flex justify-between text-sm text-slate-500"><span>Fare per passenger</span><span>{currency(Number(flight.fareAmountMinor ?? 0), String(flight.currency ?? 'KES'))}</span></div><div className="mt-3 flex justify-between text-sm text-slate-500"><span>Passenger count</span><span>{passengers.length}</span></div><div className="mt-4 flex justify-between border-t border-slate-100 pt-4 text-lg font-extrabold text-navy"><span>Total</span><span>{currency(Number(flight.fareAmountMinor ?? 0) * passengers.length, String(flight.currency ?? 'KES'))}</span></div></div></aside></div>}</>;
}

function BookingsPage() {
  const [bookings, setBookings] = useState<Booking[]>([]); const [busy, setBusy] = useState(true); const [error, setError] = useState('');
  const load = useCallback(async () => { setBusy(true); try { const result = await apiRequest<{ bookings: Booking[] }>('/bookings'); setBookings(result.bookings); setError(''); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load bookings.'); } finally { setBusy(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const cancel = async (id: string) => { if (!window.confirm('Cancel this unpaid seat hold?')) return; try { await apiRequest(`/bookings/${id}/cancel`, { method: 'POST' }); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not cancel booking.'); } };
  return <><PageTitle eyebrow="Your reservations" title="My bookings" description="Track seat holds, confirmed reservations and ticket status." action={<button onClick={() => void load()} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-extrabold text-navy"><RefreshCw className="mr-2 inline" size={14}/>Refresh</button>}/>{error && <ErrorNotice message={error}/>}{busy ? <LoadingLine/> : bookings.length === 0 ? <EmptyState title="No bookings yet" text="Flights you reserve will appear here with their reference and payment status." action={<Link to="/app/flights" className="rounded-xl bg-aviation px-4 py-3 text-sm font-extrabold text-white">Search flights</Link>}/> : <div className="grid gap-4">{bookings.map((booking) => <article key={booking.id} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><p className="text-sm font-extrabold text-navy">{booking.bookingReference}</p><StatusPill value={booking.status}/></div><p className="mt-2 text-lg font-extrabold text-navy">{booking.originCode} <ArrowRight className="mx-1 inline" size={15}/> {booking.destinationCode}</p><p className="mt-1 text-xs text-slate-400">{booking.airlineName} · {booking.flightNumber} · {dateLabel(booking.departureTime)}</p><p className="mt-2 text-xs text-slate-500">{booking.seatCount} passenger(s)</p></div><div className="text-right"><p className="text-lg font-extrabold text-navy">{currency(booking.totalAmountMinor, booking.currency)}</p>{booking.status === 'held' && booking.holdExpiresAt && <p className="mt-1 text-xs text-amber-700">Hold until {dateLabel(booking.holdExpiresAt)}</p>}</div></div><div className="mt-5 flex flex-wrap gap-2 border-t border-slate-100 pt-4">{booking.status === 'held' && <Link to={`/app/payments?booking=${booking.id}`} className="rounded-lg bg-aviation px-4 py-2.5 text-xs font-extrabold text-white">Complete payment</Link>}{booking.status === 'ticketed' && <Link to="/app/tickets" className="rounded-lg bg-sky px-4 py-2.5 text-xs font-extrabold text-aviation">View e-ticket</Link>}{['held', 'pending'].includes(booking.status) && <button onClick={() => void cancel(booking.id)} className="rounded-lg border border-slate-200 px-4 py-2.5 text-xs font-extrabold text-slate-600 hover:border-rose-200 hover:text-rose-600">Cancel hold</button>}</div></article>)}</div>}</>;
}

function EmptyState({ title, text, action }: { title: string; text: string; action?: ReactNode }) { return <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-sky text-aviation"><Plane size={21}/></div><h3 className="mt-4 text-lg font-extrabold text-navy">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-500">{text}</p>{action && <div className="mt-5">{action}</div>}</div>; }

function PaymentsPage() {
  const [bookings, setBookings] = useState<Booking[]>([]); const [payments, setPayments] = useState<Record<string, any>[]>([]); const [phone, setPhone] = useState(''); const [busy, setBusy] = useState(''); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [selectedBooking, setSelectedBooking] = useState(''); const [params] = useSearchParams();
  const load = useCallback(async () => { try { const [b, p] = await Promise.all([apiRequest<{ bookings: Booking[] }>('/bookings'), apiRequest<{ payments: Record<string, any>[] }>('/payments')]); setBookings(b.bookings.filter((booking) => booking.status === 'held' && !['initiating', 'pending', 'review_required'].includes(String(booking.paymentStatus)))); setPayments(p.payments); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load payments.'); } }, []);
  useEffect(() => { void load(); if (params.get('booking')) setSelectedBooking(params.get('booking')!); }, [load, params]);
  const pay = async (method: 'mpesa' | 'card') => {
    if (!selectedBooking) { setError('Choose a held booking first.'); return; }
    setBusy(method); setError(''); setMessage('');
    try {
      const response = await apiRequest<{ payment: { id: string; status: string; checkoutUrl?: string; message?: string } }>('/payments', { method: 'POST', body: JSON.stringify({ bookingId: selectedBooking, method, phoneNumber: phone }) });
      if (response.payment.checkoutUrl) window.location.assign(response.payment.checkoutUrl);
      else setMessage(response.payment.message ?? 'Payment request sent. Complete the prompt on your phone, then refresh payment status.');
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Payment could not be started.'); }
    finally { setBusy(''); }
  };
  return <><PageTitle eyebrow="Secure checkout" title="Payments" description="Pay for active seat holds using M-Pesa or a card. A ticket is created only after the provider confirms the payment." action={<button onClick={() => void load()} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-extrabold text-navy"><RefreshCw className="mr-2 inline" size={14}/>Refresh status</button>}/>{error && <ErrorNotice message={error}/>}{message && <div className="mb-5"><SuccessNotice message={message}/></div>}<div className="grid gap-6 xl:grid-cols-[1fr_1fr]"><section className="rounded-2xl border border-slate-200 bg-white p-6"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-sky text-aviation"><WalletCards/></div><div><h2 className="font-extrabold text-navy">Complete a booking</h2><p className="text-xs text-slate-400">Select an unpaid seat hold.</p></div></div>{bookings.length === 0 ? <div className="mt-5 rounded-xl bg-sky/60 p-4 text-sm text-slate-600">There are no active seat holds to pay. Search and reserve a flight first.</div> : <><FormField label="Booking"><select className="form-input" value={selectedBooking} onChange={(e) => setSelectedBooking(e.target.value)}><option value="">Select booking</option>{bookings.map((b) => <option key={b.id} value={b.id}>{b.bookingReference} · {b.originCode} to {b.destinationCode} · {currency(b.totalAmountMinor, b.currency)}</option>)}</select></FormField><FormField label="M-Pesa phone number"><input className="form-input" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="07XXXXXXXX or 2547XXXXXXXX"/></FormField><div className="grid gap-3 sm:grid-cols-2"><button onClick={() => void pay('mpesa')} disabled={!!busy || !selectedBooking} className="flex items-center justify-center gap-2 rounded-xl bg-emerald-600 px-4 py-3.5 text-sm font-extrabold text-white hover:bg-emerald-700 disabled:opacity-50">{busy === 'mpesa' ? 'Sending prompt...' : 'Pay with M-Pesa'} <Phone size={16}/></button><button onClick={() => void pay('card')} disabled={!!busy || !selectedBooking} className="flex items-center justify-center gap-2 rounded-xl bg-navy px-4 py-3.5 text-sm font-extrabold text-white hover:bg-aviation disabled:opacity-50">{busy === 'card' ? 'Connecting...' : 'Pay by card'} <CreditCard size={16}/></button></div><p className="mt-4 text-xs leading-5 text-slate-400">Payments are initiated on the server. Never share your M-Pesa PIN or card details with AeroNexa.</p></>}</section><section className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Payment history</h2><p className="mt-1 text-xs text-slate-400">Your latest payment attempts and confirmations.</p>{payments.length === 0 ? <p className="mt-6 text-sm text-slate-500">No payment activity yet.</p> : <div className="mt-4 divide-y divide-slate-100">{payments.map((payment) => <div key={payment.id} className="flex flex-wrap items-center justify-between gap-2 py-3"><div><p className="text-sm font-extrabold text-navy">{payment.bookingReference}</p><p className="mt-1 text-xs capitalize text-slate-400">{payment.method} · {payment.provider}</p></div><div className="text-right"><p className="text-sm font-extrabold text-navy">{currency(payment.amountMinor, payment.currency)}</p><StatusPill value={payment.status}/></div></div>)}</div>}</section></div><div className="mt-6 rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 text-aviation"/><div><p className="text-sm font-extrabold text-navy">Payment protection</p><p className="mt-1 text-xs leading-5 text-slate-500">Card payments use Stripe Checkout. M-Pesa uses Safaricom Daraja STK Push. Provider callbacks are matched to the pending payment record before a booking is ticketed.</p></div></div></div></>;
}

function PassengersPage() {
  const [passengers, setPassengers] = useState<Passenger[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [form, setForm] = useState({ givenName: '', familyName: '', dateOfBirth: '1990-01-01', email: '', phoneNumber: '' });
  const load = useCallback(async () => { setBusy(true); try { const result = await apiRequest<{ passengers: Passenger[] }>('/passengers'); setPassengers(result.passengers); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load passenger profiles.'); } finally { setBusy(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const add = async (event: FormEvent) => { event.preventDefault(); setError(''); try { await apiRequest('/passengers', { method: 'POST', body: JSON.stringify(form) }); setForm({ givenName: '', familyName: '', dateOfBirth: '1990-01-01', email: '', phoneNumber: '' }); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not save passenger.'); } };
  const remove = async (id: string) => { try { await apiRequest(`/passengers/${id}`, { method: 'DELETE' }); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not delete passenger.'); } };
  return <><PageTitle eyebrow="Traveller profiles" title="Passengers" description="Save traveller details to speed up future reservations. Names must match each traveller's travel documents."/>{error && <ErrorNotice message={error}/>}<div className="grid gap-6 xl:grid-cols-[1fr_1.2fr]"><form onSubmit={add} className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Add a passenger</h2><div className="mt-5 grid gap-3 sm:grid-cols-2"><FormField label="First name"><input required className="form-input" value={form.givenName} onChange={(e) => setForm({ ...form, givenName: e.target.value })}/></FormField><FormField label="Last name"><input required className="form-input" value={form.familyName} onChange={(e) => setForm({ ...form, familyName: e.target.value })}/></FormField><FormField label="Date of birth"><input required type="date" max={inputDateOffset(-1)} className="form-input" value={form.dateOfBirth} onChange={(e) => setForm({ ...form, dateOfBirth: e.target.value })}/></FormField><FormField label="Email"><input type="email" className="form-input" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })}/></FormField><FormField label="Phone number"><input className="form-input" value={form.phoneNumber} onChange={(e) => setForm({ ...form, phoneNumber: e.target.value })}/></FormField></div><button className="mt-2 rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white hover:bg-navy"><Plus className="mr-2 inline" size={16}/>Save passenger</button></form><section className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Saved travellers</h2>{busy ? <LoadingLine/> : passengers.length === 0 ? <p className="mt-5 text-sm text-slate-500">No saved passenger profiles.</p> : <div className="mt-4 divide-y divide-slate-100">{passengers.map((p) => <div key={p.id} className="flex items-center justify-between gap-3 py-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-full bg-sky text-aviation"><UserRound size={18}/></div><div><p className="text-sm font-extrabold text-navy">{p.givenName} {p.familyName}</p><p className="mt-1 text-xs text-slate-400">Born {p.dateOfBirth} {p.email ? `· ${p.email}` : ''}</p></div></div><button onClick={() => void remove(p.id)} aria-label="Delete passenger" className="rounded-lg p-2 text-slate-400 hover:bg-rose-50 hover:text-rose-600"><Trash2 size={16}/></button></div>)}</div>}</section></div></>;
}

function TicketsPage() {
  const [tickets, setTickets] = useState<Record<string, any>[]>([]); const [error, setError] = useState(''); const [busy, setBusy] = useState(true);
  const load = useCallback(async () => { setBusy(true); try { const result = await apiRequest<{ tickets: Record<string, any>[] }>('/tickets'); setTickets(result.tickets); setError(''); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load tickets.'); } finally { setBusy(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const checkIn = async (ticketId: string) => { try { await apiRequest(`/tickets/${ticketId}/check-in`, { method: 'POST', body: JSON.stringify({}) }); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Check-in failed.'); } };
  return <><PageTitle eyebrow="Travel documents" title="E-tickets" description="Your electronic ticket records and AeroNexa check-in status appear after your payment provider confirms the transaction. These are not airline-issued boarding passes." action={<button onClick={() => void load()} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-extrabold text-navy"><RefreshCw className="mr-2 inline" size={14}/>Refresh</button>}/>{error && <ErrorNotice message={error}/>}{busy ? <LoadingLine/> : tickets.length === 0 ? <EmptyState title="No issued tickets yet" text="Once you complete payment for a reservation, your ticket number and check-in details will appear here." action={<Link to="/app/bookings" className="rounded-xl bg-aviation px-4 py-3 text-sm font-extrabold text-white">View bookings</Link>}/> : <div className="grid gap-4 lg:grid-cols-2">{tickets.map((ticket) => <article key={ticket.id} className="rounded-2xl border border-slate-200 bg-white p-6"><div className="flex items-start justify-between"><div><p className="text-xs font-extrabold uppercase tracking-widest text-aviation">Electronic ticket</p><h2 className="mt-2 text-xl font-extrabold text-navy">{ticket.ticketNumber}</h2><p className="mt-1 text-xs text-slate-400">{ticket.bookingReference}</p></div><StatusPill value={ticket.checkInStatus}/></div><div className="my-6 grid grid-cols-3 items-center"><div><p className="text-2xl font-extrabold text-navy">{ticket.originCode}</p><p className="mt-1 text-xs text-slate-400">Origin</p></div><div className="text-center"><Plane className="mx-auto text-aviation"/><p className="mt-1 text-[10px] text-slate-400">{ticket.flightNumber}</p></div><div className="text-right"><p className="text-2xl font-extrabold text-navy">{ticket.destinationCode}</p><p className="mt-1 text-xs text-slate-400">Destination</p></div></div><div className="border-t border-dashed border-slate-200 pt-4"><p className="text-xs text-slate-400">Passenger</p><p className="font-extrabold text-navy">{ticket.passengerName}</p><p className="mt-3 text-xs text-slate-400">Departure</p><p className="text-sm font-bold text-navy">{dateLabel(ticket.departureTime)}</p></div>{ticket.checkInStatus !== 'checked_in' && <button onClick={() => void checkIn(ticket.id)} className="mt-5 w-full rounded-xl bg-aviation px-4 py-3 text-sm font-extrabold text-white hover:bg-navy">Check in online <ArrowRight className="ml-2 inline" size={15}/></button>}</article>)}</div>}</>;
}

function DocumentsPage() {
  const [documents, setDocuments] = useState<Record<string, any>[]>([]); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { try { const result = await apiRequest<{ documents: Record<string, any>[] }>('/travel-documents'); setDocuments(result.documents); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load documents.'); } }, []);
  useEffect(() => { void load(); }, [load]);
  const upload = async (file?: File) => {
    if (!file) return;
    if (file.size > 10 * 1024 * 1024) { setError('The document must be 10 MB or smaller.'); return; }
    setBusy(true); setError(''); setMessage('');
    try {
      const created = await apiRequest<{ document: { id: string }; uploadUrl: string; requiredHeaders: Record<string, string> }>('/travel-documents/upload-url', { method: 'POST', body: JSON.stringify({ fileName: file.name, contentType: file.type }) });
      const uploadResult = await fetch(created.uploadUrl, { method: 'PUT', headers: created.requiredHeaders, body: file });
      if (!uploadResult.ok) throw new Error('Secure file upload failed.');
      await apiRequest(`/travel-documents/${created.document.id}/complete`, { method: 'POST', body: JSON.stringify({}) });
      setMessage(`${file.name} was uploaded securely.`); await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Upload failed.'); }
    finally { setBusy(false); }
  };
  const openDocument = async (id: string) => { try { const result = await apiRequest<{ downloadUrl: string }>(`/travel-documents/${id}/download-url`); window.open(result.downloadUrl, '_blank', 'noopener,noreferrer'); } catch (err) { setError(err instanceof Error ? err.message : 'Could not open document.'); } };
  const remove = async (id: string) => { try { await apiRequest(`/travel-documents/${id}`, { method: 'DELETE' }); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not delete document.'); } };
  return <><PageTitle eyebrow="Private storage" title="Travel documents" description="Store passport scans, visas and supporting documents in a private storage location. Access links expire after five minutes."/>{error && <div className="mb-4"><ErrorNotice message={error}/></div>}{message && <div className="mb-4"><SuccessNotice message={message}/></div>}<div className="rounded-2xl border border-slate-200 bg-white p-6"><label className="flex cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50 px-6 py-10 text-center hover:border-aviation"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-sky text-aviation"><Upload/></div><span className="mt-3 font-extrabold text-navy">{busy ? 'Uploading securely...' : 'Choose a travel document'}</span><span className="mt-1 text-xs text-slate-400">PDF, JPG or PNG · Maximum 10 MB</span><input type="file" accept="application/pdf,image/jpeg,image/png" className="sr-only" disabled={busy} onChange={(e) => { void upload(e.target.files?.[0]); e.currentTarget.value = ''; }}/></label></div><section className="mt-6 rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Your saved documents</h2>{documents.length === 0 ? <p className="mt-4 text-sm text-slate-500">No travel documents have been uploaded.</p> : <div className="mt-4 divide-y divide-slate-100">{documents.map((doc) => <div key={doc.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-sky text-aviation"><FileText size={18}/></div><div><p className="text-sm font-extrabold text-navy">{doc.fileName}</p><p className="mt-1 text-xs text-slate-400">{doc.contentType} · <StatusPill value={doc.status}/></p></div></div><div className="flex gap-2"><button onClick={() => void openDocument(doc.id)} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-navy">Open <ExternalLink className="ml-1 inline" size={12}/></button><button onClick={() => void remove(doc.id)} className="rounded-lg p-2 text-slate-400 hover:bg-rose-50 hover:text-rose-600"><Trash2 size={15}/></button></div></div>)}</div>}</section><div className="mt-5 flex items-start gap-3 rounded-xl bg-amber-50 p-4 text-xs leading-5 text-amber-900"><ShieldCheck size={16} className="mt-0.5 shrink-0"/>Travel identity documents contain sensitive information. Upload only what is needed for your journey and remove expired documents when no longer required.</div></>;
}

function OrganizationsPage() {
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [pendingOrganizations, setPendingOrganizations] = useState<Record<string, any>[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [inviteUrl, setInviteUrl] = useState('');
  const [form, setForm] = useState({ name: '', country: 'Kenya', type: 'travel_agency', currency: 'KES' });
  const [invite, setInvite] = useState({ orgId: '', email: '', role: 'travel_agent' });

  const load = useCallback(async () => {
    setBusy(true);
    setError('');
    try {
      const result = await apiRequest<{ organizations: Organization[] }>('/organizations/mine');
      setOrganizations(result.organizations);
      setInvite((current) => ({ ...current, orgId: current.orgId || result.organizations[0]?.id || '' }));
      try {
        const pending = await apiRequest<{ organizations: Record<string, any>[] }>('/platform/organizations/pending');
        setPendingOrganizations(pending.organizations);
      } catch { setPendingOrganizations([]); }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not load organizations.');
    } finally { setBusy(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);

  const create = async (event: FormEvent) => {
    event.preventDefault(); setError(''); setMessage('');
    try {
      const result = await apiRequest<{ organization: Organization }>('/organizations', { method: 'POST', body: JSON.stringify(form) });
      setMessage(`${result.organization.name} was created and submitted for platform approval. Publishing flights becomes available when it is approved.`);
      setForm({ name: '', country: 'Kenya', type: 'travel_agency', currency: 'KES' });
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Could not create organization.'); }
  };

  const sendInvite = async (event: FormEvent) => {
    event.preventDefault(); setError(''); setMessage(''); setInviteUrl('');
    try {
      const result = await apiRequest<{ invitation: { id: string; email: string; role: string } }>(`/organizations/${invite.orgId}/invitations`, { method: 'POST', body: JSON.stringify({ email: invite.email, role: invite.role }) });
      const url = `${window.location.origin}/app/invitations/${result.invitation.id}`;
      setInviteUrl(url);
      setMessage(`Invitation created for ${invite.email}. Share the link below through your approved channel. Email delivery is not configured.`);
      setInvite((current) => ({ ...current, email: '' }));
    } catch (err) { setError(err instanceof Error ? err.message : 'Could not create invitation.'); }
  };

  const approve = async (orgId: string) => {
    setError(''); setMessage('');
    try {
      await apiRequest(`/platform/organizations/${orgId}/approve`, { method: 'POST', body: JSON.stringify({ status: 'active' }) });
      setMessage('Organization approved. Its authorized operators can now publish flight inventory.');
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Could not approve organization.'); }
  };

  const copyInvite = async () => {
    try { await navigator.clipboard.writeText(inviteUrl); setMessage('Invitation link copied to clipboard.'); }
    catch { setMessage('Copy is unavailable in this browser. Select and copy the invitation link manually.'); }
  };

  return <>
    <PageTitle eyebrow="Multi-organization access" title="Organizations" description="Create an airline or travel agency workspace, then invite colleagues with specific operational roles."/>
    {error && <div className="mb-4"><ErrorNotice message={error}/></div>}
    {message && <div className="mb-4"><SuccessNotice message={message}/></div>}
    <div className="grid gap-6 xl:grid-cols-[1fr_1fr]">
      <form onSubmit={create} className="rounded-2xl border border-slate-200 bg-white p-6">
        <div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-sky text-aviation"><Building2/></div><h2 className="font-extrabold text-navy">Create an organization</h2></div>
        <div className="mt-5">
          <FormField label="Organization name"><input className="form-input" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Company or airline name"/></FormField>
          <div className="grid gap-3 sm:grid-cols-2"><FormField label="Organization type"><select className="form-input" value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}><option value="travel_agency">Travel agency</option><option value="airline">Airline</option></select></FormField><FormField label="Country"><input className="form-input" value={form.country} onChange={(e) => setForm({ ...form, country: e.target.value })}/></FormField></div>
          <FormField label="Settlement currency"><select className="form-input" value={form.currency} onChange={(e) => setForm({ ...form, currency: e.target.value })}><option value="KES">KES – Kenyan shilling</option><option value="USD">USD – US dollar</option></select></FormField>
          <button disabled={busy} className="rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white hover:bg-navy disabled:opacity-50"><Plus className="mr-2 inline" size={16}/>Create workspace</button>
        </div>
      </form>
      <section className="rounded-2xl border border-slate-200 bg-white p-6">
        <h2 className="font-extrabold text-navy">Your organizations</h2>
        {busy ? <LoadingLine/> : organizations.length === 0 ? <p className="mt-5 text-sm text-slate-500">You do not belong to an organization yet.</p> : <div className="mt-4 space-y-3">{organizations.map((org) => <div key={org.id} className="rounded-xl border border-slate-100 p-4"><div className="flex items-start justify-between gap-2"><div><p className="font-extrabold text-navy">{org.name}</p><p className="mt-1 text-xs capitalize text-slate-400">{org.type.replace('_', ' ')} · {org.country}</p></div><StatusPill value={org.status}/></div><p className="mt-3 text-xs text-slate-500">Your role: <strong className="capitalize text-navy">{org.role.replaceAll('_', ' ')}</strong></p></div>)}</div>}
      </section>
    </div>
    <section className="mt-6 rounded-2xl border border-slate-200 bg-white p-6">
      <h2 className="font-extrabold text-navy">Invite a team member</h2><p className="mt-1 text-xs text-slate-400">Only a signed-in user with the invited email address can accept this link. Invitations expire after seven days.</p>
      <form onSubmit={sendInvite} className="mt-5 grid gap-3 md:grid-cols-[1fr_1fr_1fr_auto] md:items-end">
        <FormField label="Organization"><select required className="form-input" value={invite.orgId} onChange={(e) => setInvite({ ...invite, orgId: e.target.value })}><option value="">Select organization</option>{organizations.filter((org) => org.role === 'organization_admin').map((org) => <option key={org.id} value={org.id}>{org.name}</option>)}</select></FormField>
        <FormField label="Member email"><input type="email" required className="form-input" value={invite.email} onChange={(e) => setInvite({ ...invite, email: e.target.value })}/></FormField>
        <FormField label="Role"><select className="form-input" value={invite.role} onChange={(e) => setInvite({ ...invite, role: e.target.value })}><option value="travel_agent">Travel agent</option><option value="booking_officer">Booking officer</option><option value="operations_manager">Operations manager</option><option value="finance_officer">Finance officer</option><option value="checkin_officer">Check-in officer</option></select></FormField>
        <button disabled={!invite.orgId} className="mb-4 rounded-xl bg-navy px-5 py-3 text-sm font-extrabold text-white hover:bg-aviation disabled:opacity-40">Create invite <Send className="ml-1 inline" size={14}/></button>
      </form>
      {inviteUrl && <div className="mt-4 rounded-xl bg-sky/60 p-4"><p className="text-xs font-extrabold text-navy">Share this invitation link</p><div className="mt-2 flex flex-wrap items-center gap-2"><input readOnly className="form-input min-w-0 flex-1 bg-white" value={inviteUrl}/><button type="button" onClick={copyInvite} className="rounded-xl bg-navy px-4 py-3 text-xs font-extrabold text-white">Copy link</button></div></div>}
    </section>
    {pendingOrganizations.length > 0 && <section className="mt-6 rounded-2xl border border-amber-200 bg-amber-50/60 p-6"><h2 className="font-extrabold text-navy">Platform approval queue</h2><p className="mt-1 text-xs text-slate-500">Visible only to platform administrators.</p><div className="mt-4 space-y-3">{pendingOrganizations.map((org) => <div key={org.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-100 bg-white p-4"><div><p className="font-extrabold text-navy">{org.name}</p><p className="mt-1 text-xs text-slate-500">{org.type} · {org.country} · {org.id}</p></div><button onClick={() => approve(org.id)} className="rounded-xl bg-navy px-4 py-2.5 text-xs font-extrabold text-white">Approve organization</button></div>)}</div></section>}
  </>;
}

function AcceptInvitationPage() {
  const { inviteId = '' } = useParams();
  const [state, setState] = useState<'loading' | 'accepted' | 'error'>('loading');
  const [message, setMessage] = useState('Checking your invitation...');
  const navigate = useNavigate();
  const { user } = useAuth();
  useEffect(() => {
    if (!user) return;
    let active = true;
    apiRequest('/organizations/invitations/' + inviteId + '/accept', { method: 'POST', body: JSON.stringify({}) })
      .then(() => { if (active) { setState('accepted'); setMessage('You have joined the organization.'); } })
      .catch((err) => { if (active) { setState('error'); setMessage(err instanceof Error ? err.message : 'This invitation could not be accepted.'); } });
    return () => { active = false; };
  }, [inviteId, user]);
  if (!user) return <div className="mx-auto max-w-xl py-16 text-center"><PageTitle eyebrow="Organization invitation" title="Sign in to accept" description="Use the same email address that received this invitation."/><Link to={`/signin?next=${encodeURIComponent(`/app/invitations/${inviteId}`)}`} className="mt-4 inline-flex rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white">Sign in</Link></div>;
  return <div className="mx-auto max-w-xl rounded-3xl border border-slate-200 bg-white p-8 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-sky text-aviation"><Building2/></div><h1 className="mt-5 text-2xl font-extrabold text-navy">{state === 'accepted' ? 'Invitation accepted' : state === 'error' ? 'Invitation unavailable' : 'Accepting invitation'}</h1><p className="mt-3 text-sm leading-6 text-slate-500">{message}</p>{state !== 'loading' && <button onClick={() => navigate('/app/organizations')} className="mt-6 rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white">Open organizations</button>}</div>;
}

function FlightOperationsPage() {
  const [organizations, setOrganizations] = useState<Organization[]>([]); const [orgId, setOrgId] = useState(''); const [flights, setFlights] = useState<Record<string, any>[]>([]); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const [form, setForm] = useState({ flightNumber: '', airlineName: '', airlineCode: '', originCode: 'NBO', destinationCode: 'MBA', departureTime: `${inputDateOffset(30)}T08:00`, arrivalTime: `${inputDateOffset(30)}T09:15`, seatCapacity: 120, fareKes: '12500', cabinClass: 'economy' });
  const loadOrgs = useCallback(async () => { try { const result = await apiRequest<{ organizations: Organization[] }>('/organizations/mine'); setOrganizations(result.organizations); if (!orgId && result.organizations[0]) setOrgId(result.organizations[0].id); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load organizations.'); } }, [orgId]);
  const loadFlights = useCallback(async () => { if (!orgId) return; try { const result = await apiRequest<{ flights: Record<string, any>[] }>(`/organizations/${orgId}/flights`); setFlights(result.flights); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load flight operations.'); } }, [orgId]);
  useEffect(() => { void loadOrgs(); }, [loadOrgs]);
  useEffect(() => { void loadFlights(); }, [loadFlights]);
  const create = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); setMessage(''); try { await apiRequest('/flights', { method: 'POST', body: JSON.stringify({ organizationId: orgId, ...form, fareAmountMinor: Math.round(Number(form.fareKes) * 100), departureTime: new Date(form.departureTime).toISOString(), arrivalTime: new Date(form.arrivalTime).toISOString(), currency: organizations.find((o) => o.id === orgId)?.currency ?? 'KES' }) }); setMessage('Flight schedule and seat inventory created.'); setForm({ ...form, flightNumber: '' }); await loadFlights(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not create flight.'); } finally { setBusy(false); } };
  const changeStatus = async (id: string, status: string) => { try { await apiRequest(`/flights/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); await loadFlights(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not update flight status.'); } };
  return <><PageTitle eyebrow="Airline and agency tools" title="Flight operations" description="Publish internal flight schedules and track their seat inventory. Organization administrators and operations managers can manage schedules."/>{error && <div className="mb-4"><ErrorNotice message={error}/></div>}{message && <div className="mb-4"><SuccessNotice message={message}/></div>}{organizations.length === 0 ? <EmptyState title="Create an organization first" text="Flight schedules belong to an airline or agency workspace. Set up an organization before publishing inventory." action={<Link to="/app/organizations" className="rounded-xl bg-aviation px-4 py-3 text-sm font-extrabold text-white">Create organization</Link>}/> : <><div className="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white p-4"><div><p className="text-xs font-extrabold uppercase tracking-wider text-slate-400">Active workspace</p><p className="mt-1 font-extrabold text-navy">{organizations.find((o) => o.id === orgId)?.name}</p></div><select className="form-input max-w-sm" value={orgId} onChange={(e) => setOrgId(e.target.value)}>{organizations.map((org) => <option key={org.id} value={org.id}>{org.name}</option>)}</select></div><div className="grid gap-6 xl:grid-cols-[1fr_1fr]"><form onSubmit={create} className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Publish a flight</h2><p className="mt-1 text-xs text-slate-400">Seat availability and fares are stored in the same inventory record used by the booking transaction.</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><FormField label="Flight number"><input className="form-input" required value={form.flightNumber} onChange={(e) => setForm({ ...form, flightNumber: e.target.value })} placeholder="ANX 204"/></FormField><FormField label="Airline name"><input className="form-input" required value={form.airlineName} onChange={(e) => setForm({ ...form, airlineName: e.target.value })}/></FormField><FormField label="Airline code"><input className="form-input" maxLength={3} value={form.airlineCode} onChange={(e) => setForm({ ...form, airlineCode: e.target.value.toUpperCase() })} /></FormField><FormField label="Cabin class"><select className="form-input" value={form.cabinClass} onChange={(e) => setForm({ ...form, cabinClass: e.target.value })}><option value="economy">Economy</option><option value="premium_economy">Premium economy</option><option value="business">Business</option><option value="first">First</option></select></FormField><FormField label="Origin airport"><input className="form-input uppercase" maxLength={3} required value={form.originCode} onChange={(e) => setForm({ ...form, originCode: e.target.value.toUpperCase() })}/></FormField><FormField label="Destination airport"><input className="form-input uppercase" maxLength={3} required value={form.destinationCode} onChange={(e) => setForm({ ...form, destinationCode: e.target.value.toUpperCase() })}/></FormField><FormField label="Departure time"><input type="datetime-local" required className="form-input" value={form.departureTime} onChange={(e) => setForm({ ...form, departureTime: e.target.value })}/></FormField><FormField label="Arrival time"><input type="datetime-local" required className="form-input" value={form.arrivalTime} onChange={(e) => setForm({ ...form, arrivalTime: e.target.value })}/></FormField><FormField label="Seat capacity"><input type="number" min="1" max="600" required className="form-input" value={form.seatCapacity} onChange={(e) => setForm({ ...form, seatCapacity: Number(e.target.value) })}/></FormField><FormField label={`Fare per passenger (${organizations.find((o) => o.id === orgId)?.currency ?? 'KES'})`}><input type="number" min="1" step="0.01" required className="form-input" value={form.fareKes} onChange={(e) => setForm({ ...form, fareKes: e.target.value })}/></FormField></div><button disabled={busy} className="mt-3 rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white hover:bg-navy disabled:opacity-50">{busy ? 'Publishing...' : 'Publish flight'} <Plus className="ml-1 inline" size={15}/></button></form><section className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Published schedules</h2>{flights.length === 0 ? <p className="mt-5 text-sm text-slate-500">No schedules in this organization yet.</p> : <div className="mt-4 space-y-3">{flights.map((flight) => <div key={flight.id} className="rounded-xl border border-slate-100 p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-extrabold text-navy">{flight.flightNumber}</p><p className="mt-1 text-xs text-slate-400">{flight.originCode} to {flight.destinationCode} · {dateLabel(flight.departureTime)}</p><p className="mt-2 text-xs text-slate-500">{flight.availableSeats}/{flight.seatCapacity} seats · {currency(flight.fareAmountMinor, flight.currency)}</p></div><StatusPill value={flight.status}/></div><div className="mt-3 flex flex-wrap gap-2">{['scheduled', 'boarding', 'departed', 'arrived', 'delayed', 'cancelled'].filter((status) => status !== flight.status).map((status) => <button key={status} onClick={() => void changeStatus(flight.id, status)} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-[10px] font-bold capitalize text-slate-500 hover:border-aviation hover:text-aviation">Set {status}</button>)}</div></div>)}</div>}</section></div></>}</>;
}

function NotificationsPage() {
  const [items, setItems] = useState<Record<string, any>[]>([]); const [error, setError] = useState('');
  const load = useCallback(async () => { try { const result = await apiRequest<{ notifications: Record<string, any>[] }>('/notifications'); setItems(result.notifications); } catch (err) { setError(err instanceof Error ? err.message : 'Could not load notifications.'); } }, []);
  useEffect(() => { void load(); }, [load]);
  const markRead = async (id: string) => { try { await apiRequest(`/notifications/${id}/read`, { method: 'POST', body: JSON.stringify({}) }); await load(); } catch (err) { setError(err instanceof Error ? err.message : 'Could not update notification.'); } };
  return <><PageTitle eyebrow="Travel updates" title="Notifications" description="Booking confirmations, expiring seat holds and important account updates."/>{error && <ErrorNotice message={error}/>}{items.length === 0 ? <EmptyState title="You're all caught up" text="New booking and payment updates will appear here."/> : <div className="rounded-2xl border border-slate-200 bg-white p-5">{items.map((item) => <div key={item.id} className="flex items-start justify-between gap-4 border-b border-slate-100 py-4 last:border-0"><div className="flex gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-sky text-aviation"><Bell size={17}/></div><div><p className="font-extrabold text-navy">{item.title}</p><p className="mt-1 text-sm leading-6 text-slate-500">{item.body}</p><p className="mt-2 text-[10px] text-slate-400">{item.createdAt?.toDate ? dateLabel(item.createdAt.toDate().toISOString()) : 'Recent'}</p></div></div>{!item.readAt && <button onClick={() => void markRead(item.id)} className="shrink-0 rounded-lg bg-sky px-3 py-2 text-[10px] font-extrabold text-aviation">Mark read</button>}</div>)}</div>}</>;
}

function SettingsPage() {
  const { user } = useAuth();
  const [displayName, setDisplayName] = useState(user?.displayName ?? ''); const [phoneNumber, setPhoneNumber] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  useEffect(() => { apiRequest<{ user: { displayName?: string; phoneNumber?: string } }>('/me').then((result) => { setDisplayName(result.user.displayName ?? ''); setPhoneNumber(result.user.phoneNumber ?? ''); }).catch(() => undefined); }, []);
  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); setMessage(''); try { await apiRequest('/profile', { method: 'PATCH', body: JSON.stringify({ displayName, phoneNumber }) }); if (auth?.currentUser) await updateProfile(auth.currentUser, { displayName }); setMessage('Your account profile has been updated.'); } catch (err) { setError(err instanceof Error ? err.message : 'Could not save settings.'); } finally { setBusy(false); } };
  return <><PageTitle eyebrow="Account preferences" title="Settings" description="Update your profile and review the security configuration of your account."/>{error && <div className="mb-4"><ErrorNotice message={error}/></div>}{message && <div className="mb-4"><SuccessNotice message={message}/></div>}<div className="grid gap-6 xl:grid-cols-[1fr_1fr]"><form onSubmit={save} className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Personal information</h2><p className="mt-1 text-xs text-slate-400">This profile is used for your AeroNexa workspace.</p><div className="mt-5"><FormField label="Display name"><input required className="form-input" value={displayName} onChange={(e) => setDisplayName(e.target.value)}/></FormField><FormField label="Email address"><input disabled className="form-input bg-slate-50" value={user?.email ?? ''}/></FormField><FormField label="Phone number"><input className="form-input" value={phoneNumber} onChange={(e) => setPhoneNumber(e.target.value)}/></FormField></div><button disabled={busy} className="rounded-xl bg-aviation px-5 py-3 text-sm font-extrabold text-white hover:bg-navy disabled:opacity-50">{busy ? 'Saving...' : 'Save profile'}</button></form><section className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-extrabold text-navy">Account security</h2><div className="mt-5 space-y-4">{[{ icon: <BadgeCheck/>, title: 'Firebase Authentication', text: 'Identity tokens are verified by the API on protected routes.' }, { icon: <LockKeyhole/>, title: 'Server-side permissions', text: 'Organization roles and booking ownership are checked by trusted services.' }, { icon: <ShieldCheck/>, title: 'Private travel documents', text: 'Documents use short-lived signed access links and private storage paths.' }].map((item) => <div key={item.title} className="flex gap-3 border-b border-slate-100 pb-4 last:border-0"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-sky text-aviation">{item.icon}</div><div><p className="text-sm font-extrabold text-navy">{item.title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{item.text}</p></div></div>)}</div><Link to="/" className="mt-3 inline-flex items-center gap-2 text-xs font-extrabold text-aviation">Visit public home <ArrowUpRight size={14}/></Link></section></div></>;
}

function App() {
  return <AuthProvider><ConnectionStatus/><Routes><Route path="/" element={<Home/>}/><Route path="/flights" element={<><PublicNav/><main className="container-wide py-12"><SearchFlightsPage/></main><Footer/></>}/><Route path="/destinations" element={<DestinationsPage/>}/><Route path="/about" element={<AboutPage/>}/><Route path="/contact" element={<ContactPage/>}/><Route path="/signin" element={<AuthPage mode="signin"/>}/><Route path="/register" element={<AuthPage mode="register"/>}/><Route path="/app/*" element={<Protected><DashboardLayout/></Protected>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></AuthProvider>;
}

export default App;
